  col:"violet",goals:[["guess","Watch it guess, as sure as a fact"],["ask","Make it ask Mei instead of guessing"],["cite","Get 6,212, with Mei's definition"],["same","Give a new analyst's agent the same answer"]],
  setT:"What the agent has",setSay:"{what}: {v}.",runL:"Who asks",stepsT:"What it does",stepsIdle:"Nothing asked yet.",resT:"What it says",
  idle:"Ask, and see what the agent reads and what it answers.",working:"It reads, then counts…",
