  start:"Each agent reads its own copy. Change them, then ask.",
  alt:"Each agent's source as chips, the steps when asked, and the three answers side by side.",
  col:"blue",goals:[["three","Get three answers, none showing its source"],["lowest","Plan from the lowest, and leave projects out"],["agree","Get 168 from every agent, with evidence"],["deleted","Delete the private copies"]],
  setT:"What each agent reads",setSay:"{what}: {v}.",runL:"Play",stepsT:"What happens",stepsIdle:"Nothing asked yet.",resT:"What came of it",
  idle:"Ask for Health's active research projects.",working:"Three agents count…",
  keep:{gone:"Copies deleted"},
  set:[{k:"a1",label:"Anil's agent",def:"copy",opts:[["copy","A report's spreadsheet","spreadsheet",0],["gov","Governed tables and tools","governed",1]]},
   {k:"a2",label:"A colleague's agent",def:"copy",opts:[["copy","A copy of the table","table copy",0],["gov","Governed tables and tools","governed",1]]},
   {k:"a3",label:"Another colleague's",def:"copy",opts:[["copy","A folder of reports","reports folder",0],["gov","Governed tables and tools","governed",1]]}],
